{"invariants": ["ack_outstanding || ((countdown == 64'd0) && (service_token == TOKEN_ZERO))", "!ack_outstanding || ((countdown >= 64'd1) && (countdown <= SERVICE_STEPS))", "!ack_outstanding || (service_token == (TOKEN_ONE << (SERVICE_STEPS - countdown)))", "!ack_outstanding || request_pending", "!ack_outstanding || !pass_valid"], "verilog": "module imaging_irq_ack_cell #(
