{"invariants": ["scope_active || (pattern_valid == {ENTRIES{1'b0}})", "!scope_active || arm_seen || (pattern_valid == ARM_MASK)", "!scope_active || !arm_seen || start_seen || (pattern_valid == START_MASK)", "!scope_active || !start_seen || finish_seen || (pattern_valid == FINISH_MASK)", "!scope_active || !finish_seen || (pattern_valid == {ENTRIES{1'b0}})"], "verilog": "module scoped_bridge_token_cam #(
