    localparam integer ARM_COUNT = ENTRIES / 32'd4;
    localparam integer START_COUNT = ENTRIES / 32'd4;
    localparam [DATA_W-1:0] ENTRY_LIMIT = DATA_W'(ENTRIES);
    localparam [ENTRIES-1:0] ARM_MASK =
        {ENTRIES{1'b1}} >> (ENTRIES - ARM_COUNT);
    localparam [ENTRIES-1:0] START_MASK =
